ar, discipular, servir y esperamos con certeza la resurrecci\\u00f3n final para vida eterna con Dios.<\\/p>\",\"paragraph_spacing\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=000b116\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true,\"isLocked\":true},{\"id\":\"0291db3\",\"elType\":\"container\",\"settings\":{\"_title\":\"Pesta\\u00f1a #2\",\"content_width\":\"full\"},\"elements\":[{\"id\":\"c7a7c0e\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"5\",\"row\":\"5\",\"isLinked\":true,\"unit\":\"px\",\"size\":5},\"width\":{\"unit\":\"%\",\"size\":100},\"width_mobile\":{\"unit\":\"%\",\"size\":100},\"padding\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"e56c3c0\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"20\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"1\",\"left\":\"0\",\"isLinked\":false},\"border_color\":\"#e5e7eb\",\"animation\":\"fadeInUp\"},\"elements\":[{\"id\":\"9fb22b5\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"5\",\"row\":\"5\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"5\"}},\"elements\":[{\"id\":\"b39b321\",\"elType\":\"widget\",\"settings\":{\"title\":\"Bautismo por inmersi\\u00f3n\",\"header_size\":\"h3\",\"align\":\"left\",\"title_color\":\"#111827\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=e8d16ad\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"7a5d568\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p style=\\\"font-size: 17.5px; color: #4b5563; line-height: 1.6;\\\">Lo realizamos como testimonio p\\u00fablico tras la profesi\\u00f3n personal de fe en Jes\\u00fas.<\\/p>\",\"paragraph_spacing\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=000b116\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"b1d7225\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"20\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"1\",\"left\":\"0\",\"isLinked\":false},\"border_color\":\"#e5e7eb\",\"animation\":\"fadeInUp\"},\"elements\":[{\"id\":\"77d8b99\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"5\",\"row\":\"5\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"5\"}},\"elements\":[{\"id\":\"88ab653\",\"elType\":\"widget\",\"settings\":{\"title\":\"La Cena del Se\\u00f1or\",\"header_size\":\"h3\",\"align\":\"left\",\"title_color\":\"#111827\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=e8d16ad\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"14cb02f\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p style=\\\"font-size: 17.5px; color: #4b5563; line-height: 1.6;\\\">La celebramos cada domingo en memoria del sacrificio y la resurrecci\\u00f3n de Jesucristo.<\\/p>\",\"paragraph_spacing\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=000b116\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"a45aa7b\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"20\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"1\",\"left\":\"0\",\"isLinked\":false},\"border_color\":\"#e5e7eb\",\"animation\":\"fadeInUp\"},\"elements\":[{\"id\":\"1015288\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"5\",\"row\":\"5\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"5\"}},\"elements\":[{\"id\":\"4d4661e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Comuni\\u00f3n, adoraci\\u00f3n y estudio b\\u00edblico\",\"header_size\":\"h3\",\"align\":\"left\",\"title_color\":\"#111827\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=e8d16ad\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"5fe57d3\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p style=\\\"font-size: 17.5px; color: #4b5563; line-height: 1.6;\\\">Nos reunimos para alabar a Dios, orar, edificar la iglesia con los dones espirituales y profundizar en las Escrituras.<\\/p>\",\"paragraph_spacing\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=000b116\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"0815f8f\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"20\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"1\",\"left\":\"0\",\"isLinked\":false},\"border_color\":\"#e5e7eb\",\"animation\":\"fadeInUp\"},\"elements\":[{\"id\":\"6870eff\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"5\",\"row\":\"5\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"5\"}},\"elements\":[{\"id\":\"f3f7568\",\"elType\":\"widget\",\"settings\":{\"title\":\"Fe en acci\\u00f3n y servicio\",\"header_size\":\"h3\",\"align\":\"left\",\"title_color\":\"#111827\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=e8d16ad\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"870c133\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p style=\\\"font-size: 17.5px; color: #4b5563; line-height: 1.6;\\\">Vivimos una fe pr\\u00e1ctica reflejada en el amor al pr\\u00f3jimo, las buenas obras como fruto de la salvaci\\u00f3n y la proclamaci\\u00f3n del Evangelio.<\\/p>\",\"paragraph_spacing\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=000b116\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"1b6e76a\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\",\"flex_gap\":{\"column\":\"20\",\"row\":\"20\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"20\"},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"border_border\":\"none\",\"border_width\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"1\",\"left\":\"0\",\"isLinked\":false},\"border_color\":\"#e5e7eb\",\"animation\":\"fadeInUp\"},\"elements\":[{\"id\":\"5e66fca\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"flex_gap\":{\"column\":\"5\",\"row\":\"5\",\"isLinked\":true,\"unit\":\"px\",\"size\":\"5\"}},\"elements\":[{\"id\":\"69a9d8c\",\"elType\":\"widget\",\"settings\":{\"title\":\"Liderazgo b\\u00edblico y autonom\\u00eda local\",\"header_size\":\"h3\",\"align\":\"left\",\"title_color\":\"#111827\",\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=e8d16ad\"}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"d619a6f\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p style=\\\"font-size: 17.5px; color: #4b5563; line-height: 1.6;\\\">Fomentamos el cuidado pastoral a trav\\u00e9s de creyentes con testimonio \\u00edntegro, manteniendo autonom\\u00eda y cooperaci\\u00f3n fraternal entre iglesias.<\\/p>\",\"paragraph_spacing\":{\"unit\":\"px\",\"size\":5,\"sizes\":[]},\"__globals__\":{\"typography_typography\":\"globals\\/typography?id=000b116\"}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true}],\"isInner\":true,\"isLocked\":true}]}],\"isInner\":true}],\"isInner\":false},{\"id\":\"71c5b5f\",\"elType\":\"container\",\"settings\":{\"background_background\":\"classic\",\"background_color\":\"#FFFFFF\",\"flex_align_items\":\"center\",\"flex_direction\":\"column\",\"padding\":{\"bottom\":\"80\",\"isLinked\":false,\"left\":\"30\",\"right\":\"30\",\"top\":\"80\",\"unit\":\"px\"}},\"elements\":[{\"id\":\"23c196a\",\"elType\":\"widget\",\"settings\":{\"header_size\":\"p\",\"_animation\":\"fadeInUp\",\"align\":\"center\",\"title\":\"Gu\\u00eda de Visita\",\"title_color\":\"#135BEC\",\"typography_font_family\":\"DM Sans\",\"typography_font_size\":{\"size\":14,\"unit\":\"px\"},\"typography_font_weight\":\"700\",\"typography_letter_spacing\":{\"size\":3,\"unit\":\"px\"},\"typography_text_transform\":\"uppercase\",\"typography_typography\":\"custom\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"7879c2e\",\"elType\":\"widget\",\"settings\":{\"_animation\":\"fadeInUp\",\"_animation_delay\":200,\"_margin\":{\"bottom\":\"15\",\"isLinked\":false,\"left\":\"0\",\"right\":\"0\",\"top\":\"5\",\"unit\":\"px\"},\"align\":\"center\",\"title\":\"Primera Vez en la Iglesia\",\"title_color\":\"#111827\",\"typography_font_family\":\"Playfair Display\",\"typography_font_size\":{\"size\":40,\"unit\":\"px\"},\"typography_font_weight\":\"600\",\"typography_typography\":\"custom\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"ccf6443\",\"elType\":\"widget\",\"settings\":{\"_animation\":\"fadeInUp\",\"_animation_delay\":300,\"_margin\":{\"bottom\":\"50\",\"isLinked\":false,\"left\":\"0\",\"right\":\"0\",\"top\":\"0\",\"unit\":\"px\"},\"align\":\"center\",\"editor\":\"<p style=\\\"color: #6B7280; font-size: 18px; max-width: 600px; margin: 0 auto; line-height: 1.7;\\\">No importa de d\\u00f3nde vengas o qu\\u00e9 experiencia tengas. Te recibimos con los brazos abiertos. Aqu\\u00ed tienes todo lo que necesitas saber:<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"a085bf8\",\"elType\":\"widget\",\"settings\":{\"html\":\"<style>\\n.icpr-guide {\\n  font-family: \'DM Sans\', sans-serif;\\n  max-width: 900px;\\n  margin: 0 auto;\\n  display: flex;\\n  flex-direction: column;\\n  gap: 16px;\\n}\\n.icpr-guide .step-card {\\n  display: flex;\\n  align-items: flex-start;\\n  gap: 24px;\\n  padding: 24px 28px;\\n  background: #F9FAFB;\\n  border-radius: 18px;\\n  border: 1px solid #E5E7EB;\\n  transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);\\n  position: relative;\\n  overflow: hidden;\\n}\\n.icpr-guide .step-card::before {\\n  content: \'\';\\n  position: absolute;\\n  left: 0;\\n  top: 0;\\n  width: 4px;\\n  height: 100%;\\n  background: linear-gradient(180deg, #135BEC, #3679FF);\\n  transform: scaleY(0);\\n  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);\\n  transform-origin: top;\\n}\\n.icpr-guide .step-card:hover {\\n  background: #FFFFFF;\\n  transform: translateX(8px);\\n  box-shadow: 0 10px 28px rgba(19, 91, 236, 0.08);\\n  border-color: #CBD5E1;\\n}\\n.icpr-guide .step-card:hover::before {\\n  transform: scaleY(1);\\n}\\n.icpr-guide .step-num {\\n  min-width: 44px;\\n  height: 44px;\\n  border-radius: 50%;\\n  background: linear-gradient(135deg, #135BEC, #3679FF);\\n  color: #FFFFFF;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  font-size: 18px;\\n  font-weight: 700;\\n  flex-shrink: 0;\\n  transition: all 0.3s ease;\\n  box-shadow: 0 4px 12px rgba(19, 91, 236, 0.2);\\n}\\n.icpr-guide .step-card:hover .step-num {\\n  transform: scale(1.1);\\n}\\n.icpr-guide .step-content {\\n  flex: 1;\\n}\\n.icpr-guide .step-content h3, .icpr-guide .step-content h4 {\\n  font-family: \'Playfair Display\', serif;\\n  font-size: 21px;\\n  font-weight: 700;\\n  color: #111827;\\n  margin: 0 0 6px;\\n  line-height: 1.3;\\n}\\n.icpr-guide .step-content p {\\n  color: #4B5563;\\n  font-size: 17px;\\n  line-height: 1.65;\\n  margin: 0;\\n}\\n.icpr-guide .step-icon-arrow {\\n  font-size: 20px;\\n  color: #135BEC;\\n  opacity: 0;\\n  transform: translateX(-8px);\\n  transition: all 0.3s ease;\\n  align-self: center;\\n}\\n.icpr-guide .step-card:hover .step-icon-arrow {\\n  opacity: 1;\\n  transform: translateX(0);\\n}\\n@media (max-width: 767px) {\\n  .icpr-guide .step-card {\\n    flex-direction: column;\\n    gap: 14px;\\n    padding: 20px;\\n  }\\n  .icpr-guide .step-card:hover {\\n    transform: translateY(-3px);\\n  }\\n  .icpr-guide .step-icon-arrow {\\n    display: none;\\n  }\\n}\\n<\\/style>\\n\\n<div class=\\\"icpr-guide\\\">\\n  <div class=\\\"step-card\\\">\\n    <div class=\\\"step-num\\\">1<\\/div>\\n    <div class=\\\"step-content\\\">\\n      <h3>\\ud83d\\udccd Llega sin prisa<\\/h3>\\n      <p>Te recomendamos llegar unos 10 minutos antes para aparcar y entrar con tranquilidad. Los <strong>domingos nos reunimos a las 11:30h<\\/strong> en Calle Don Quijote, 42, Puerto del Rosario.<\\/p>\\n    <\\/div>\\n    <div class=\\\"step-icon-arrow\\\">\\u2192<\\/div>\\n  <\\/div>\\n\\n  <div class=\\\"step-card\\\">\\n    <div class=\\\"step-num\\\">2<\\/div>\\n    <div class=\\\"step-content\\\">\\n      <h3>\\ud83e\\udd1d Te damos la bienvenida<\\/h3>\\n      <p>Al llegar, alguien de nuestra iglesia te recibir\\u00e1 y te ofrecer\\u00e1 un caf\\u00e9. Ven como te sientas m\\u00e1s c\\u00f3modo, no existe ning\\u00fan c\\u00f3digo de vestimenta.<\\/p>\\n    <\\/div>\\n    <div class=\\\"step-icon-arrow\\\">\\u2192<\\/div>\\n  <\\/div>\\n\\n  <div class=\\\"step-card\\\">\\n    <div class=\\\"step-num\\\">3<\\/div>\\n    <div class=\\\"step-content\\\">\\n      <h3>\\ud83c\\udfb5 Adoraci\\u00f3n y ense\\u00f1anza<\\/h3>\\n      <p>Comenzamos con un tiempo de alabanza y c\\u00e1nticos a Dios, seguido de una predicaci\\u00f3n expositiva y pr\\u00e1ctica basada en la Biblia. Duraci\\u00f3n aproximada: 1 hora y media.<\\/p>\\n    <\\/div>\\n    <div class=\\\"step-icon-arrow\\\">\\u2192<\\/div>\\n  <\\/div>\\n\\n  <div class=\\\"step-card\\\">\\n    <div class=\\\"step-num\\\">4<\\/div>\\n    <div class=\\\"step-content\\\">\\n      <h3>\\ud83c\\udf5e La Mesa del Se\\u00f1or<\\/h3>\\n      <p>Cada domingo celebramos la Cena del Se\\u00f1or en memoria del sacrificio y resurrecci\\u00f3n de Jesucristo. Como visitante, puedes <strong>participar si eres creyente y est\\u00e1s bautizado<\\/strong>.<\\/p>\\n    <\\/div>\\n    <div class=\\\"step-icon-arrow\\\">\\u2192<\\/div>\\n  <\\/div>\\n\\n  <div class=\\\"step-card\\\">\\n    <div class=\\\"step-num\\\">5<\\/div>\\n    <div class=\\\"step-content\\\">\\n      <h3>\\ud83e\\udd32 \\u00bfTengo que dar dinero al ir?<\\/h3>\\n      <p><strong>No, absolutamente no.<\\/strong> La ofrenda es un acto de adoraci\\u00f3n voluntario exclusivo de los miembros. Los visitantes no tienen ning\\u00fan tipo de compromiso ni obligaci\\u00f3n econ\\u00f3mica.<\\/p>\\n    <\\/div>\\n    <div class=\\\"step-icon-arrow\\\">\\u2192<\\/div>\\n  <\\/div>\\n\\n  <div class=\\\"step-card\\\">\\n    <div class=\\\"step-num\\\">6<\\/div>\\n    <div class=\\\"step-content\\\">\\n      <h3>\\u2615 Comparte con nosotros<\\/h3>\\n      <p>Al terminar la reuni\\u00f3n, te invitamos a quedarte unos minutos. Nos encantar\\u00e1 saludarte en persona, responder tus dudas y compartir un tiempo de conversaci\\u00f3n.<\\/p>\\n    <\\/div>\\n    <div class=\\\"step-icon-arrow\\\">\\u2192<\\/div>\\n  <\\/div>\\n<\\/div>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"1545f73\",\"elType\":\"container\",\"settings\":{\"background_background\":\"classic\",\"background_color\":\"#F8FAFC\",\"flex_align_items\":\"center\",\"flex_direction\":\"column\",\"padding\":{\"bottom\":\"80\",\"isLinked\":false,\"left\":\"30\",\"right\":\"30\",\"top\":\"80\",\"unit\":\"px\"}},\"elements\":[{\"id\":\"2751b2f\",\"elType\":\"widget\",\"settings\":{\"header_size\":\"p\",\"_animation\":\"fadeInUp\",\"align\":\"center\",\"title\":\"Pr\\u00f3ximamente\",\"title_color\":\"#135BEC\",\"typography_font_family\":\"DM Sans\",\"typography_font_size\":{\"size\":14,\"unit\":\"px\"},\"typography_font_weight\":\"700\",\"typography_letter_spacing\":{\"size\":3,\"unit\":\"px\"},\"typography_text_transform\":\"uppercase\",\"typography_typography\":\"custom\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"eab0744\",\"elType\":\"widget\",\"settings\":{\"_animation\":\"fadeInUp\",\"_animation_delay\":200,\"_margin\":{\"bottom\":\"10\",\"isLinked\":false,\"left\":\"0\",\"right\":\"0\",\"top\":\"5\",\"unit\":\"px\"},\"align\":\"center\",\"title\":\"Eventos Especiales\",\"title_color\":\"#111827\",\"typography_font_family\":\"Playfair Display\",\"typography_font_size\":{\"size\":40,\"unit\":\"px\"},\"typography_font_weight\":\"600\",\"typography_typography\":\"custom\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"05bb56c\",\"elType\":\"widget\",\"settings\":{\"_animation\":\"fadeInUp\",\"_animation_delay\":300,\"_margin\":{\"bottom\":\"50\",\"isLinked\":false,\"left\":\"0\",\"right\":\"0\",\"top\":\"0\",\"unit\":\"px\"},\"align\":\"center\",\"editor\":\"<p><em>\\u00a1Ap\\u00fantalos en tu agenda! No te pierdas esta cita especial.<\\/em><\\/p>\"},\"elements\":[],\"widgetT