"content_width\":\"full\",\"_animation\":\"fadeInRight\",\"background_background\":\"classic\",\"background_color\":\"#FFFFFF\",\"border_border\":\"solid\",\"border_color\":\"#E5E7EB\",\"border_radius\":{\"bottom\":\"20\",\"isLinked\":true,\"left\":\"20\",\"right\":\"20\",\"top\":\"20\",\"unit\":\"px\"},\"border_width\":{\"bottom\":\"1\",\"isLinked\":true,\"left\":\"1\",\"right\":\"1\",\"top\":\"1\",\"unit\":\"px\"},\"flex_direction\":\"column\",\"padding\":{\"bottom\":\"36\",\"isLinked\":false,\"left\":\"36\",\"right\":\"36\",\"top\":\"36\",\"unit\":\"px\"},\"flex_align_items\":\"stretch\",\"width\":{\"size\":50,\"unit\":\"%\"},\"width_mobile\":{\"size\":100,\"unit\":\"%\"},\"box_shadow_box_shadow\":{\"blur\":25,\"color\":\"rgba(0,0,0,0.04)\",\"horizontal\":0,\"spread\":0,\"vertical\":8},\"box_shadow_box_shadow_type\":\"yes\",\"overflow\":\"hidden\",\"animation\":\"fadeInUp\",\"animation_delay\":300,\"width_tablet\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[{\"id\":\"b9b1776\",\"elType\":\"widget\",\"settings\":{\"header_size\":\"h3\",\"_margin\":{\"bottom\":\"15\",\"isLinked\":false,\"left\":\"0\",\"right\":\"0\",\"top\":\"0\",\"unit\":\"px\"},\"align\":\"left\",\"title\":\"Escr\\u00edbenos\",\"title_color\":\"#1A1A1A\",\"typography_font_family\":\"Playfair Display\",\"typography_font_size\":{\"size\":28,\"unit\":\"px\"},\"typography_font_weight\":\"700\",\"typography_typography\":\"custom\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"de774c3\",\"elType\":\"widget\",\"settings\":{\"_margin\":{\"bottom\":\"20\",\"isLinked\":false,\"left\":\"0\",\"right\":\"0\",\"top\":\"0\",\"unit\":\"px\"},\"editor\":\"<p style=\\\"color: #70757D; font-size: 17.5px; line-height: 1.6;\\\">Nos encantar\\u00eda saber de ti. Env\\u00edanos tu consulta y te responderemos lo antes posible.\\u00a0<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"26e9e46\",\"elType\":\"widget\",\"settings\":{\"html\":\"<style>\\n.icpr-contact-form {\\n  font-family: \'DM Sans\', sans-serif;\\n  width: 100%;\\n  box-sizing: border-box;\\n}\\n.icpr-contact-form .form-group {\\n  margin-bottom: 16px;\\n  position: relative;\\n}\\n.icpr-contact-form .form-row {\\n  display: flex;\\n  gap: 14px;\\n}\\n.icpr-contact-form .form-row .form-group {\\n  flex: 1;\\n}\\n.icpr-contact-form label {\\n  display: block;\\n  font-size: 14px;\\n  font-weight: 700;\\n  color: #70757D;\\n  margin-bottom: 6px;\\n  text-transform: uppercase;\\n  letter-spacing: 0.5px;\\n}\\n.icpr-contact-form input,\\n.icpr-contact-form textarea {\\n  width: 100%;\\n  padding: 13px 18px;\\n  border: 1.5px solid #E5E7EB;\\n  border-radius: 14px;\\n  font-size: 17px;\\n  font-family: \'DM Sans\', sans-serif;\\n  color: #1A1A1A;\\n  background: #F7F7F8;\\n  transition: all 0.25s ease;\\n  outline: none;\\n  box-sizing: border-box;\\n}\\n.icpr-contact-form input:focus,\\n.icpr-contact-form textarea:focus {\\n  border-color: #C85A3A;\\n  background: #FFFFFF;\\n  box-shadow: 0 0 0 3px rgba(200, 90, 58, 0.12);\\n}\\n.icpr-contact-form textarea {\\n  min-height: 120px;\\n  resize: vertical;\\n}\\n.icpr-contact-form .submit-btn {\\n  width: 100%;\\n  padding: 16px 32px;\\n  background: linear-gradient(135deg, #C85A3A 0%, #D66D4F 100%);\\n  color: #FFFFFF;\\n  border: none;\\n  border-radius: 9999px;\\n  font-size: 16px;\\n  font-weight: 700;\\n  font-family: \'DM Sans\', sans-serif;\\n  cursor: pointer;\\n  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 8px;\\n  box-shadow: 0 4px 14px rgba(200, 90, 58, 0.22);\\n}\\n.icpr-contact-form .submit-btn:hover {\\n  transform: translateY(-2px);\\n  box-shadow: 0 8px 22px rgba(200, 90, 58, 0.30);\\n}\\n.icpr-contact-form .submit-btn:active {\\n  transform: translateY(0);\\n}\\n.icpr-contact-form .success-msg {\\n  display: none;\\n  text-align: center;\\n  padding: 18px 20px;\\n  background: #ECFDF5;\\n  border: 1px solid #A7F3D0;\\n  border-radius: 16px;\\n  color: #065F46;\\n  font-weight: 600;\\n  font-size: 17px;\\n  line-height: 1.5;\\n  animation: formFadeIn 0.4s ease;\\n}\\n@keyframes formFadeIn {\\n  from { opacity: 0; transform: translateY(10px); }\\n  to { opacity: 1; transform: translateY(0); }\\n}\\n@media (max-width: 640px) {\\n  .icpr-contact-form .form-row {\\n    flex-direction: column;\\n    gap: 0;\\n  }\\n}\\n<\\/style>\\n\\n<form class=\\\"icpr-contact-form\\\" onsubmit=\\\"event.preventDefault(); const btn=this.querySelector(\'.submit-btn\'); const msg=this.querySelector(\'.success-msg\'); btn.textContent=\'Enviando...\'; setTimeout(() => { btn.style.display=\'none\'; msg.style.display=\'block\'; }, 1000);\\\">\\n  <div class=\\\"form-row\\\">\\n    <div class=\\\"form-group\\\">\\n      <label>Nombre *<\\/label>\\n      <input type=\\\"text\\\" placeholder=\\\"Tu nombre\\\" required>\\n    <\\/div>\\n    <div class=\\\"form-group\\\">\\n      <label>Email *<\\/label>\\n      <input type=\\\"email\\\" placeholder=\\\"tu@email.com\\\" required>\\n    <\\/div>\\n  <\\/div>\\n  <div class=\\\"form-group\\\">\\n    <label>Tel\\u00e9fono<\\/label>\\n    <input type=\\\"tel\\\" placeholder=\\\"Tu tel\\u00e9fono (opcional)\\\">\\n  <\\/div>\\n  <div class=\\\"form-group\\\">\\n    <label>Mensaje *<\\/label>\\n    <textarea placeholder=\\\"\\u00bfEn qu\\u00e9 podemos ayudarte?\\\" required><\\/textarea>\\n  <\\/div>\\n  <button type=\\\"submit\\\" class=\\\"submit-btn\\\">\\n    <span>Enviar Mensaje<\\/span>\\n    <svg width=\\\"18\\\" height=\\\"18\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"2\\\"><line x1=\\\"22\\\" y1=\\\"2\\\" x2=\\\"11\\\" y2=\\\"13\\\"><\\/line><polygon points=\\\"22 2 15 22 11 13 2 9 22 2\\\"><\\/polygon><\\/svg>\\n  <\\/button>\\n  <div class=\\\"success-msg\\\">\\n    \\u2728 \\u00a1Gracias por escribirnos! Hemos recibido tu mensaje y nos pondremos en contacto contigo muy pronto.\\n  <\\/div>\\n<\\/form>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":true}],\"isInner\":true}],\"isInner\":false}]');
